class Solution {
public:
    int countBlocks(BigArray* nums) {
        long long n = nums->size();
        long long i = 0;
        int blocks = 0;
        while (i < n) {
            blocks++;
            int target = nums->at(i);
            long long lo = i, hi = n;
            while (lo < hi) {
                long long mid = lo + (hi - lo) / 2;
                if (nums->at(mid) == target) lo = mid + 1;
                else hi = mid;
            }
            i = lo;
        }
        return blocks;
    }
};

